 ## [Unreleased]

+### Fixed
+
+- On pi-durable hosts, shell output that arrives after the `typescript` call settled (its session failed, or the host aborted it) is dropped. Before, pi-durable's `Tool call … has settled` error escaped the command's stdout handler and crashed the host process, as in a pi-action run whose storage failed.
+
 ## [0.36.2] - 2026-11-13

 ### Added
diff --git a/src/durable/tool.ts b/src/durable/tool.ts
index 53ef450..d8b5c3e 100644
--- a/src/durable/tool.ts
+++ b/src/durable/tool.ts
@@ -170,6 +170,28 @@ async function prepareHost(call: DurableCall) {
   return { deadline, stop, questions, ctx, agent, model, images };
 }

+/**
+ * Records each shell event, and streams a command's output to the host's observers; the result replaces it. The call
+ * can settle while a command still prints (its session failed, or the host aborted it): pi-durable then takes no more
+ * output, and the chunks left in the pipe have nowhere to go. They are dropped, because a throw here would escape
+ * the child's stdout handler and crash the host process.
+ */
+function shellProgress(
+  api: Pick<ToolExecutionApi, "output">,
+  progress: Pick<ExecutionProgressController, "recordShell">,
+): (event: ShellProgressEvent) => void {
+  let open = true;
+  return (event) => {
+    progress.recordShell(event);
+    if (event.phase !== "output" || !open) return;
+    try {
+      api.output(event.chunk);
+    } catch {
+      open = false;
+    }
+  };
+}
+
 async function runDurableProgram(call: DurableCall) {
   const { api, context, params, functions } = call;
   const { functionState, commitFunctionState, savedFunctionService, recoverableCalls } = functions;
@@ -207,11 +229,7 @@ async function runDurableProgram(call: DurableCall) {
           commitFunctionState,
           activity: functionActivity,
           promotionSuggestions,
-          onShellProgress: (event: ShellProgressEvent) => {
-            executionProgress.recordShell(event);
-            // Running output for the host's observers; the result replaces it.
-            if (event.phase === "output") api.output(event.chunk);
-          },
+          onShellProgress: shellProgress(api, executionProgress),
           images,
           completedCalls,
           // Hosts such as pi-action run unattended on shared repositories: project files ask first.
diff --git a/test/durable/settled-output.test.ts b/test/durable/settled-output.test.ts
new file mode 100644
index 0000000..35c34ac
--- /dev/null
+++ b/test/durable/settled-output.test.ts
@@ -0,0 +1,81 @@
+import { mkdir, mkdtemp, rm, stat } from "node:fs/promises";
+import { tmpdir } from "node:os";
+import { join } from "node:path";
+
+import { BACKGROUND_CONTEXT as context } from "@earendil-works/chord/context";
+import { createModels } from "@earendil-works/pi-ai/models";
+import {
+  fauxAssistantMessage,
+  fauxProvider,
+  fauxToolCall,
+} from "@earendil-works/pi-ai/providers/faux";
+import { createRegistry, Harness, MemoryStorage } from "@earendil-works/pi-durable";
+import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
+
+import { createPitDurableExtension } from "../../src/durable/index.js";
+
+let root: string;
+let cwd: string;
+
+beforeEach(async () => {
+  root = await mkdtemp(join(tmpdir(), "pit-settled-"));
+  cwd = join(root, "project");
+  await mkdir(cwd, { recursive: true });
+});
+
+afterEach(async () => {
+  await rm(root, { recursive: true, force: true });
+});
+
+/** A MemoryStorage whose commits fail once `fail` is set, as a git storage whose ref moved does. */
+function failingStorage(): { storage: MemoryStorage; fail: () => void } {
+  const storage = new MemoryStorage();
+  let failing = false;
+  const commit = storage.commit.bind(storage);
+  storage.commit = async (...args: Parameters<MemoryStorage["commit"]>) => {
+    if (failing) throw new Error("storage failed");
+    return commit(...args);
+  };
+  return { storage, fail: () => (failing = true) };
+}
+
+describe("shell output after the call settled", () => {
+  it("is dropped instead of crashing the host when the session fails while a command prints", async () => {
+    const faux = fauxProvider({ provider: "faux", models: [{ id: "faux-model" }] });
+    const models = createModels();
+    models.setProvider(faux.provider);
+    const registry = createRegistry();
+    registry.install(createPitDurableExtension({ agentDir: join(root, "agent") }));
+    const { storage, fail } = failingStorage();
+    const harness = await Harness.open(storage, { models, registry }, context);
+    const conversation = await harness.root(context, {
+      agent: { model: { provider: "faux", modelId: "faux-model" }, cwd },
+    });
+    faux.setResponses([
+      fauxAssistantMessage(
+        fauxToolCall("typescript", {
+          code: `async ({ shell: { exec } }) => exec("touch started; yes tick")`,
+        }),
+        { stopReason: "toolUse" },
+      ),
+      fauxAssistantMessage("done"),
+    ]);
+    const errors: unknown[] = [];
+    const onError = (error: unknown) => errors.push(error);
+    process.on("uncaughtException", onError);
+    try {
+      const submission = await conversation.submit({ type: "input", content: "run" }, context);
+      await vi.waitFor(() => stat(join(cwd, "started")), { timeout: 10_000, interval: 10 });
+      fail();
+      await expect(submission.wait(context)).rejects.toThrow(
+        "Session failed after a storage error",
+      );
+      // The output still in the pipe arrives after the call settled.
+      await new Promise((resolve) => setTimeout(resolve, 2_000));
+    } finally {
+      process.off("uncaughtException", onError);
+      await harness.close(context).catch(() => undefined);
+    }
+    expect(errors.map(String)).toEqual([]);
+  });
+});
